func TestResolveSigningKey(t *testing.T) {
	rawKey := []byte("0123456789abcdef")
	whsec := "whsec_" + base64.StdEncoding.EncodeToString(rawKey)

	t.Run("plain secret used as-is", func(t *testing.T) {
		key, err := resolveSigningKey("my-plain-secret")
		require.NoError(t, err)
		require.Equal(t, []byte("my-plain-secret"), key)
	})

	t.Run("whsec_ prefix is base64-decoded", func(t *testing.T) {
		key, err := resolveSigningKey(whsec)
		require.NoError(t, err)
		require.Equal(t, rawKey, key)
	})

	t.Run("whsec_ with invalid base64 fails loudly", func(t *testing.T) {
		_, err := resolveSigningKey("whsec_not!valid!base64!")
		require.Error(t, err)
	})
}

func TestGenerateSigningSecret(t *testing.T) {
	secret, err := GenerateSigningSecret()
	require.NoError(t, err)
	require.True(t, strings.HasPrefix(secret, "whsec_"), "generated secret must use the whsec_ prefix")
	require.NoError(t, ValidateSigningSecret(secret), "generated secret must pass validation")

	key, err := resolveSigningKey(secret)
	require.NoError(t, err)
	require.Len(t, key, 32, "generated secret must decode to 32 raw bytes")

	other, err := GenerateSigningSecret()
	require.NoError(t, err)
	require.NotEqual(t, secret, other, "each generated secret must be unique")
}

func TestValidateSigningSecret(t *testing.T) {
	tests := []struct {
		name    string
		secret  string
		wantErr bool
	}{
		{name: "empty is allowed", secret: "", wantErr: false},
		{name: "printable ascii", secret: "abcDEF123!@#", wantErr: false},
		{name: "valid whsec_", secret: "whsec_" + base64.StdEncoding.EncodeToString([]byte("key")), wantErr: false},
		{name: "newline rejected", secret: "abc\ndef", wantErr: true},
		{name: "carriage return rejected", secret: "abc\rdef", wantErr: true},
		{name: "tab rejected", secret: "abc\tdef", wantErr: true},
		{name: "non-ascii rejected", secret: "abc€def", wantErr: true},
		{name: "whsec_ with invalid base64 rejected", secret: "whsec_not!base64", wantErr: true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			err := ValidateSigningSecret(tc.secret)
			if tc.wantErr {
				require.Error(t, err)
			} else {
				require.NoError(t, err)
			}
		})
	}
}

// TestPostSignsRequest verifies the end-to-end Standard Webhooks signature so a
// receiver following the documented verification recipe will accept our requests.
func TestPostSignsRequest(t *testing.T) {
	// httptest listens on 127.0.0.1, which the SSRF guard blocks by default.
	prev := AllowPrivateIPs
	AllowPrivateIPs = true
	defer func() { AllowPrivateIPs = prev }()

	rawKey := []byte("0123456789abcdef0123456789abcdef")
	cases := []struct {
		name   string
		secret string
		key    []byte
	}{
		{name: "plain secret", secret: "plain-secret-value", key: []byte("plain-secret-value")},
		{name: "whsec_ secret", secret: "whsec_" + base64.StdEncoding.EncodeToString(rawKey), key: rawKey},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			var gotID, gotTimestamp, gotSignature string
			var gotBody []byte
			server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				gotID = r.Header.Get("webhook-id")
				gotTimestamp = r.Header.Get("webhook-timestamp")
				gotSignature = r.Header.Get("webhook-signature")
				gotBody, _ = io.ReadAll(r.Body)
				_, _ = w.Write([]byte(`{"code":0}`))
			}))
			defer server.Close()

			err := Post(&WebhookRequestPayload{
				URL:           server.URL,
				ActivityType:  "memos.memo.created",
				Creator:       "users/1",
				SigningSecret: tc.secret,
			})
			require.NoError(t, err)

			require.True(t, strings.HasPrefix(gotID, "msg_"), "webhook-id should be prefixed with msg_")
			require.NotEmpty(t, gotTimestamp)
			require.True(t, strings.HasPrefix(gotSignature, "v1,"), "signature should carry the v1 version tag")

			// Recompute the signature the way a receiver would and confirm it matches.
			mac := hmac.New(sha256.New, tc.key)
			mac.Write([]byte(gotID + "." + gotTimestamp + "."))
			mac.Write(gotBody)
			want := base64.StdEncoding.EncodeToString(mac.Sum(nil))
			require.Equal(t, "v1,"+want, gotSignature)
		})
	}
}

// TestPostWithoutSecretSetsNoSignatureHeaders ensures unsigned webhooks stay unsigned.
func TestPostWithoutSecretSetsNoSignatureHeaders(t *testing.T) {
	prev := AllowPrivateIPs
	AllowPrivateIPs = true
	defer func() { AllowPrivateIPs = prev }()

	var hasSignatureHeaders bool
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hasSignatureHeaders = r.Header.Get("webhook-id") != "" ||
			r.Header.Get("webhook-timestamp") != "" ||
			r.Header.Get("webhook-signature") != ""
		_, _ = w.Write([]byte(`{"code":0}`))
	}))
	defer server.Close()

	err := Post(&WebhookRequestPayload{
		URL:          server.URL,
		ActivityType: "memos.memo.created",
		Creator:      "users/1",
	})
	require.NoError(t, err)
	require.False(t, hasSignatureHeaders, "no signature headers should be set when no secret is configured")
}

1	package s3presign
2	
3	import (
4		"context"
5		"log/slog"
6		"time"
7	
8		"google.golang.org/protobuf/proto"
9		"google.golang.org/protobuf/types/known/timestamppb"
10	
11		"github.com/usememos/memos/internal/storage/s3"
12		storepb "github.com/usememos/memos/proto/gen/store"
13		"github.com/usememos/memos/store"
14	)
15	
16	type Runner struct {
17		Store *store.Store
18	}
19	
20	func NewRunner(store *store.Store) *Runner {
21		return &Runner{
22			Store: store,
23		}
24	}
25	
26	// Schedule runner every 12 hours.
27	const runnerInterval = time.Hour * 12
28	
29	func (r *Runner) Run(ctx context.Context) {
30		ticker := time.NewTicker(runnerInterval)
31		defer ticker.Stop()
32	
33		for {
34			select {
35			case <-ticker.C:
36				r.RunOnce(ctx)
37			case <-ctx.Done():
38				return
39			}
40		}
41	}
42	
43	func (r *Runner) RunOnce(ctx context.Context) {
44		r.CheckAndPresign(ctx)
45	}
46	
47	func (r *Runner) CheckAndPresign(ctx context.Context) {
48		instanceStorageSetting, err := r.Store.GetInstanceStorageSetting(ctx)
49		if err != nil {
50			return
51		}
52	
53		s3StorageType := storepb.AttachmentStorageType_S3
54		// Limit attachments to a reasonable batch size
55		const batchSize = 100
56		offset := 0
57	
58		for {
59			limit := batchSize
60			attachments, err := r.Store.ListAttachments(ctx, &store.FindAttachment{
61				GetBlob:     false,
62				StorageType: &s3StorageType,
63				Limit:       &limit,
64				Offset:      &offset,
65			})
66			if err != nil {
67				slog.Error("Failed to list attachments for presigning", "error", err)
68				return
69			}
70	
71			// Break if no more attachments
72			if len(attachments) == 0 {
73				break
74			}
75	
76			// Process batch of attachments
77			presignCount := 0
78			for _, attachment := range attachments {
79				payload := cloneAttachmentPayload(attachment.Payload)
80				s3ObjectPayload := payload.GetS3Object()
81				if s3ObjectPayload == nil {
82					continue
83				}
84	
85				if s3ObjectPayload.LastPresignedTime != nil {
86					// Skip if the presigned URL is still valid for the next 4 days.
87					// The expiration time is set to 5 days.
88					if time.Now().Before(s3ObjectPayload.LastPresignedTime.AsTime().Add(4 * 24 * time.Hour)) {
89						continue
90					}
91				}
92	
93				s3Config := instanceStorageSetting.GetS3Config()
94				if s3ObjectPayload.S3Config != nil {
95					s3Config = s3ObjectPayload.S3Config
96				}
97				if s3Config == nil {
98					slog.Error("S3 config is not found")
99					continue
100				}
101	
102				s3Client, err := s3.NewClient(ctx, s3Config)
103				if err != nil {
104					slog.Error("Failed to create S3 client", "error", err)
105					continue
106				}
107	
108				presignURL, err := s3Client.PresignGetObject(ctx, s3ObjectPayload.Key)
109				if err != nil {
110					slog.Error("Failed to presign URL", "error", err, "attachmentID", attachment.ID)
111					continue
112				}
113	
114				s3ObjectPayload.S3Config = s3Config
115				s3ObjectPayload.LastPresignedTime = timestamppb.New(time.Now())
116				if err := r.Store.UpdateAttachment(ctx, &store.UpdateAttachment{
117					ID:        attachment.ID,
118					Reference: &presignURL,
119					Payload:   payload,
120				}); err != nil {
121					slog.Error("Failed to update attachment", "error", err, "attachmentID", attachment.ID)
122					continue
123				}
124				presignCount++
125			}
126	
127			slog.Info("Presigned batch of S3 attachments", "batchSize", len(attachments), "presigned", presignCount)
128	
129			// Move to next batch
130			offset += len(attachments)
131		}
132	}
133	
134	func cloneAttachmentPayload(payload *storepb.AttachmentPayload) *storepb.AttachmentPayload {
135		if payload == nil {
136			return nil
137		}
138		cloned, ok := proto.Clone(payload).(*storepb.AttachmentPayload)
139		if !ok {
140			return nil
141		}
142		return cloned
143	}
